import{_ as l,E as n,h as o,c as u,b as a,f as t,H as r,w as i,l as p,a3 as h,a4 as m}from"./chunks/framework.B_fYP6Of.js";const A=JSON.parse('{"title":"Ingestion and enrichment DAG","description":"Trace how a revised document moves through parsing, chunking, and entity extraction, and see which outputs should be rebuilt after a source correction.","frontmatter":{"title":"Ingestion and enrichment DAG","description":"Trace how a revised document moves through parsing, chunking, and entity extraction, and see which outputs should be rebuilt after a source correction.","teaser":"A corrected page arrives while the old version is still being indexed. The important question is which version a reader can actually retrieve."},"headers":[],"relativePath":"architecture/ingestion.md","filePath":"architecture/ingestion.md"}'),g={name:"architecture/ingestion.md"};function f(b,e,v,k,w,x){const s=n("LabArticleHeader"),c=n("Mermaid"),d=n("LabScroll");return o(),u("div",null,[e[1]||(e[1]=a("h1",{id:"ingestion-and-enrichment-dag",tabindex:"-1"},[t("Ingestion and enrichment DAG "),a("a",{class:"header-anchor",href:"#ingestion-and-enrichment-dag","aria-label":'Permalink to "Ingestion and enrichment DAG"'},"​")],-1)),r(s),e[2]||(e[2]=a("p",null,[a("span",{class:"status-label"},"DRAFT · EXECUTION ENGINE OPEN")],-1)),e[3]||(e[3]=a("p",null,"Suppose a report arrives with a corrected name while a worker is extracting relationships from the previous edition. A successful worker can still produce an obsolete result. Before publication, the system needs to check exactly which source revision each piece of work used.",-1)),e[4]||(e[4]=a("p",null,"The draft represents those dependencies as a directed acyclic graph (DAG). The graph records which outputs depend on which inputs. One durable orchestrator owns retries and execution state. Parsing has separate CPU, GPU, model quotas, and database publication capacity so chat can keep serving readers.",-1)),e[5]||(e[5]=a("h2",{id:"artifact-dependencies",tabindex:"-1"},[t("Artifact dependencies "),a("a",{class:"header-anchor",href:"#artifact-dependencies","aria-label":'Permalink to "Artifact dependencies"'},"​")],-1)),r(d,{kind:"diagram",label:"diagram for Artifact dependencies"},{default:i(()=>[(o(),p(h,null,{default:i(()=>[r(c,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20TD%0A%20%20accTitle%3A%20Two%20outputs%20from%20a%20source%20revision%0A%20%20accDescr%3A%20After%20parsing%20and%20normalization%2C%20retrieval%20chunks%20feed%20lexical%20and%20vector%20indexes.%20A%20second%20branch%20extracts%20mentions%2C%20resolves%20entities%2C%20and%20publishes%20a%20graph%20for%20grounded%20augmentation.%0A%20%20SOURCE%5B%22Immutable%20source%20revision%22%5D%20--%3E%20PARSE%5B%22Structured%20document%20and%20source%20anchors%22%5D%0A%20%20PARSE%20--%3E%20NORMAL%5B%22Normalization%20and%20linguistic%20annotations%22%5D%0A%20%20NORMAL%20--%3E%20CHUNKS%5B%22Retrieval%20chunks%22%5D%0A%20%20CHUNKS%20--%3E%20FTS%5B%22Lexical%20index%22%5D%0A%20%20CHUNKS%20--%3E%20EMB%5B%22Embeddings%20and%20vector%20index%22%5D%0A%20%20FTS%20--%3E%20SEARCH%5B%22Search%20readiness%20policy%22%5D%0A%20%20EMB%20--%3E%20SEARCH%0A%20%20NORMAL%20--%3E%20WINDOWS%5B%22Extraction%20windows%20and%20context%22%5D%0A%20%20WINDOWS%20--%3E%20MENTIONS%5B%22Mentions%2C%20coreference%2C%20relation%20candidates%22%5D%0A%20%20MENTIONS%20--%3E%20RESOLVE%5B%22Entity%20resolution%20and%20validated%20claims%22%5D%0A%20%20RESOLVE%20--%3E%20GRAPH%5B%22Published%20graph%20projection%22%5D%0A%20%20GRAPH%20--%3E%20AUG%5B%22Grounded%20augmentation%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1}))]),_:1}),e[6]||(e[6]=m('<p>Read the diagram as a map of artifacts. A parser can process a document or a useful batch in one job. The output records its source revision, relevant context, and input fingerprint. That record tells the next worker what it can reuse when one page changes.</p><h2 id="parsing-and-chunking" tabindex="-1">Parsing and chunking <a class="header-anchor" href="#parsing-and-chunking" aria-label="Permalink to &quot;Parsing and chunking&quot;">​</a></h2><p>Preserve the original file and a structured representation of headings, paragraphs, tables, captions, lists, and code. OCR and normalization retain mappings to source locations and document revisions. Retrieval chunks link to larger parent sections. Extraction windows include the context needed for pronouns, aliases, and relationships spanning boundaries.</p><p>Docling is a candidate for structure-aware and token-aware chunking. Parser accuracy and source-anchor fidelity require tests on the actual formats. <a href="https://docling-project.github.io/docling/concepts/chunking/" target="_blank" rel="noreferrer">Docling chunking</a></p><h2 id="nlp-and-entity-extraction" tabindex="-1">NLP and entity extraction <a class="header-anchor" href="#nlp-and-entity-extraction" aria-label="Permalink to &quot;NLP and entity extraction&quot;">​</a></h2><p>Start with a passage that contains a pronoun, an acronym, and a domain term. Choose sentence boundaries, entity recognition, coreference, and relationship extraction for the language and task. Keep each annotation alongside the original wording. Then check which domain concepts a general-purpose named-entity recognizer misses.</p><p>Entity linking is a separate decision from mention detection. Candidate generation can use identifiers, aliases, types, dates, surrounding entities, and semantic context. Resolve when supported; preserve unresolved local identities otherwise. Record merge and split decisions so corrections can be reversed. spaCy documents context-based linking to canonical IDs as a distinct component. <a href="https://spacy.io/api/entitylinker" target="_blank" rel="noreferrer">spaCy entity linking</a></p><h2 id="claims-and-augmentation" tabindex="-1">Claims and augmentation <a class="header-anchor" href="#claims-and-augmentation" aria-label="Permalink to &quot;Claims and augmentation&quot;">​</a></h2><p>Store claims with evidence spans, negation, modality, time, document revision, and extraction provenance. For example, a possible future acquisition remains a possibility attributed to a source. It is not automatically an established ownership relationship.</p><p>Build grounded entity descriptions, section context, aliases, table descriptions, or summaries as separate derived artifacts. Synthetic questions are optional and must improve measured retrieval. An augmentation does not become an independent source or a second corroborating citation. Microsoft GraphRAG provides a reference separation of graph extraction, augmentation, summaries, and embeddings. <a href="https://microsoft.github.io/graphrag/index/default_dataflow/" target="_blank" rel="noreferrer">GraphRAG indexing</a></p><h2 id="durable-execution-contract" tabindex="-1">Durable execution contract <a class="header-anchor" href="#durable-execution-contract" aria-label="Permalink to &quot;Durable execution contract&quot;">​</a></h2><p>An artifact fingerprint includes input hashes, source revision, relevant entity-resolution snapshot, stage implementation, schema, model, prompt, and configuration versions. A successfully committed output can be reused only when those dependencies match.</p><p>The orchestrator owns attempts, leases, timeouts, bounded retries, and readiness. Outputs commit idempotently before task acknowledgment. External model calls can have ambiguous completion after failure; persisted output reuse reduces duplication without promising exactly-once inference. Check current revision and attempt authority before publishing.</p><p>NATS can deliver source-change and committed-readiness events. If Dagster or Temporal owns internal activities, use that engine&#39;s scheduling semantics. Do not create a competing retry loop in broker consumers. Store an outbox entry with the committed output, then publish boundary events with deduplication and reconciliation.</p><h2 id="readiness-and-corrections" tabindex="-1">Readiness and corrections <a class="header-anchor" href="#readiness-and-corrections" aria-label="Permalink to &quot;Readiness and corrections&quot;">​</a></h2><p>Track lexical, vector, graph, and augmentation readiness separately, per revision. <code>search_ready</code> is a defined policy over the capabilities required by a given search route. Optional enrichment failures do not remove already usable source text.</p><p>When a revision changes, invalidate affected descendants. An entity-resolution correction rebuilds affected claims and derived profiles; embeddings change only if they depend on those modified artifacts. A deleted revision retracts its supporting evidence. Late work cannot promote an obsolete revision.</p><p>The knowledge graph may contain cycles. Refinement uses a bounded extraction/validation/repair sequence or an explicitly bounded task, with new output versions. It must have a stopping rule.</p><h2 id="orchestrator-decision" tabindex="-1">Orchestrator decision <a class="header-anchor" href="#orchestrator-decision" aria-label="Permalink to &quot;Orchestrator decision&quot;">​</a></h2><p>Evaluate Dagster&#39;s asset/dependency model for ETL lineage and backfills and Temporal&#39;s durable workflows for long-lived per-document execution. Select one progression owner. Workflow state storage is an operational decision separate from SQLite retrieval storage. <a href="https://dagster.io/docs/guides/build/assets/modeling-etl-pipelines" target="_blank" rel="noreferrer">Dagster ETL</a>, <a href="https://docs.temporal.io/workflow-execution" target="_blank" rel="noreferrer">Temporal workflows</a></p><h2 id="study-and-compare" tabindex="-1">Study and compare <a class="header-anchor" href="#study-and-compare" aria-label="Permalink to &quot;Study and compare&quot;">​</a></h2><p>The <a href="/knowledge-lab/research/implementation-resources">implementation resources</a> link parsing, extraction, and orchestration repositories. The <a href="/knowledge-lab/research/concepts">concept guide</a> explains entity linking and workflow durability. Read the <a href="/knowledge-lab/research/recent-developments">research and release notes</a> before choosing an upstream dependency or assuming a release is stable.</p>',22))])}const E=l(g,[["render",f]]);export{A as __pageData,E as default};
